import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}
M = NS["m"]

path = "budget.xlsx"

with zipfile.ZipFile(path) as z:
    names = z.namelist()

    # Shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall(f"{{{M}}}si"):
            text = "".join(t.text or "" for t in si.iter(f"{{{M}}}t"))
            shared.append(text)

    # Workbook: sheet names in order
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = wb_root.find(f"{{{M}}}sheets")
    sheet_entries = [(s.get("name"), s.get(f"{{{NS['r']}}}id")) for s in sheets]

    # Map rId -> target file
    rel_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rel_root:
        rel_map[rel.get("Id")] = rel.get("Target")

    all_rows = []
    for name, rid in sheet_entries:
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        print(f"=== Sheet: {name} ===")
        sheet_root = ET.fromstring(z.read(target))
        rows = {}
        for c in sheet_root.iter(f"{{{M}}}c"):
            ref = c.get("r")
            t = c.get("t")
            v_el = c.find(f"{{{M}}}v")
            is_el = c.find(f"{{{M}}}is")
            if t == "s" and v_el is not None:
                val = shared[int(v_el.text)]
            elif t == "inlineStr" and is_el is not None:
                val = "".join(x.text or "" for x in is_el.iter(f"{{{M}}}t"))
            elif t == "b":
                val = v_el.text == "1" if v_el is not None else None
            elif t == "str":
                val = v_el.text if v_el is not None else None
            elif v_el is not None:
                try:
                    val = float(v_el.text)
                except (TypeError, ValueError):
                    val = v_el.text
            else:
                val = None
            rows[ref] = val
        # Print in row order
        import re
        coord = {}
        for ref in rows:
            m = re.match(r"([A-Z]+)(\d+)", ref)
            col = 0
            for ch in m.group(1):
                col = col * 26 + (ord(ch) - 64)
            coord[(int(m.group(2)), col)] = rows[ref]
        if coord:
            max_row = max(r for r, _ in coord)
            max_col = max(c for _, c in coord)
            for r in range(1, max_row + 1):
                line = []
                for c in range(1, max_col + 1):
                    line.append(coord.get((r, c)))
                print(r, line)
        all_rows.append((name, coord))

